import { useEffect, useState } from 'react'
import { BufferGeometry, Mesh, type Object3D } from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import markersUrl from './assets/whiteboard-tools.glb?url'
import eraserUrl from './assets/eraser.glb?url'

/**
 * The whiteboard's tools as real 3D models.
 *
 * - Markers: from ProtoGen's Alyx-Physics room (projects/Alyx-Physics, `parts.glb` with its baked
 *   color/normal/ORM maps), cut down to the three markers.
 * - Eraser: `eraser.glb`, generated by scripts/build-eraser.mjs: a gray expanded-polystyrene block
 *   (fused beads, raised rim around a recessed top) on a white felt pad, with baked textures.
 *
 * Each model is re-based into a frame the board can use directly, and consumers clone it:
 * - marker: nib tip at the origin, barrel along +Y (0.1465 m long);
 * - eraser: felt face at z = 0 facing −Z (toward the board), block up +Z, long side along X.
 */
export interface ToolModels {
  markers: Record<'black' | 'blue' | 'red', Object3D>
  eraser: Object3D
}

/** Real sizes (meters) of the models, for layout and the eraser's footprint. */
export const MARKER_LENGTH = 0.1465
export const MARKER_RADIUS = 0.0105
export const ERASER_SIZE = { w: 0.13, h: 0.05, height: 0.0323 }

const MARKER_SOURCES = {
  black: 'Alyx_Marker_Black_Mesh',
  blue: 'Alyx_Marker_Blue_Mesh',
  red: 'Alyx_Marker_Red_Mesh',
} as const

let pending: Promise<ToolModels | null> | null = null
let loaded: ToolModels | null = null

export function loadToolModels(): Promise<ToolModels | null> {
  const loader = new GLTFLoader()
  pending ??= Promise.all([loader.loadAsync(markersUrl), loader.loadAsync(eraserUrl)])
    .then(([markers, eraser]) => {
      const marker = (name: string): Object3D => {
        let mesh: Mesh | undefined
        markers.scene.traverse((o) => {
          if (!mesh && o instanceof Mesh && (o.name === name || o.parent?.name === name)) mesh = o
        })
        if (!mesh) throw new Error(`whiteboard-tools.glb has no ${name}`)
        // The source barrel runs along Z with the nib at −Z (z = −0.0745): put the tip at the origin, barrel up +Y.
        const g = (mesh.geometry as BufferGeometry).clone()
        g.translate(0, 0, 0.0745)
        g.rotateX(-Math.PI / 2)
        g.computeBoundingSphere()
        return new Mesh(g, mesh.material)
      }
      loaded = {
        markers: { black: marker(MARKER_SOURCES.black), blue: marker(MARKER_SOURCES.blue), red: marker(MARKER_SOURCES.red) },
        // Already built in the tool frame.
        eraser: eraser.scene,
      }
      return loaded
    })
    .catch((err) => {
      // The board still works with the simple stand-ins.
      console.warn('Whiteboard tool models failed to load', err)
      return null
    })
  return pending
}

/** The tool models once loaded (null until then, or if they failed to load). */
export function useToolModels(): ToolModels | null {
  const [models, setModels] = useState(loaded)
  useEffect(() => {
    let live = true
    if (!loaded) void loadToolModels().then((m) => live && setModels(m))
    return () => {
      live = false
    }
  }, [])
  return models
}

/** A copy of a tool model for one place in the scene (geometry and materials are shared). */
export function placeModel(model: Object3D, name: string): Object3D {
  const o = model.clone()
  o.name = name
  o.traverse((c) => {
    c.raycast = () => {}
  })
  return o
}
